class Preview extends StatefulWidget{final Book b;const Preview(this.b,{super.key});@override State<Preview> createState()=>_PreviewState();}class _PreviewState extends State<Preview>{int p=1;@override Widget build(BuildContext c)=>Scaffold(backgroundColor:ink,appBar:AppBar(backgroundColor:ink,foregroundColor:Colors.white,title:Text('${widget.b.title}  $p/10')),body:Column(children:[Expanded(child:Container(margin:const EdgeInsets.all(16),padding:const EdgeInsets.all(28),color:const Color(0xFFFFFCF5),child:ListView(children:[Text('$p. Bölüm',textAlign:TextAlign.center,style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:25),const Text('Bu alan kitabın ücretsiz önizlemesidir. Yayındaki eserlerde yalnızca ilk 10 sayfa okuyucuya gösterilecektir.\n\nOkuyucu sayfalar arasında ilerleyebilir; 10. sayfadan sonra satın alma ekranına yönlendirilir.',style:TextStyle(fontSize:18,height:1.8))]))),Padding(padding:const EdgeInsets.all(16),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[IconButton(onPressed:p>1?()=>setState(()=>p--):null,icon:const Icon(Icons.chevron_left,color:gold)),Text('$p / 10',style:const TextStyle(color:Colors.white)),IconButton(onPressed:p<10?()=>setState(()=>p++):null,icon:const Icon(Icons.chevron_right,color:gold))]))]));}
